-- Fortune's Weave: every unit's stat growths (the percent chance each stat rises on a level
-- up), from a player-made table Matt shared. The Units Block's chart gets the nine stats,
-- and each unit gets a new revision on Stable with its numbers added (anything else on the
-- card stays as it is). Units already carrying these numbers are skipped, so it's safe to
-- rerun. Starter data: src/data/pages/fortunes-weave-growths.ts.

update public.game_blocks
set stats = $g$[{"key":"hp","label":"HP","better":"high"},{"key":"str","label":"Str","better":"high"},{"key":"mag","label":"Mag","better":"high"},{"key":"spd","label":"Spd","better":"high"},{"key":"dex","label":"Dex","better":"high"},{"key":"def","label":"Def","better":"high"},{"key":"res","label":"Res","better":"high"},{"key":"lck","label":"Lck","better":"high"},{"key":"cha","label":"Cha","better":"high"}]$g$::jsonb
where game_id = 'fortunes-weave' and block_key = 'units';

do $$
declare r jsonb; c record; rid bigint;
begin
  for r in select * from jsonb_array_elements($g$[{"slug":"eshmel","stats":{"hp":50,"str":45,"mag":45,"spd":45,"dex":45,"def":35,"res":35,"lck":40,"cha":50}},{"slug":"hong-hua","stats":{"hp":40,"str":30,"mag":45,"spd":45,"dex":45,"def":30,"res":45,"lck":30,"cha":40}},{"slug":"troy","stats":{"hp":40,"str":45,"mag":45,"spd":50,"dex":40,"def":30,"res":30,"lck":30,"cha":30}},{"slug":"cai","stats":{"hp":45,"str":45,"mag":40,"spd":45,"dex":45,"def":35,"res":35,"lck":40,"cha":40}},{"slug":"dietrich","stats":{"hp":50,"str":45,"mag":30,"spd":50,"dex":60,"def":40,"res":30,"lck":50,"cha":60}},{"slug":"theodora","stats":{"hp":70,"str":50,"mag":30,"spd":40,"dex":40,"def":40,"res":30,"lck":30,"cha":50}},{"slug":"leda","stats":{"hp":40,"str":35,"mag":35,"spd":65,"dex":50,"def":30,"res":35,"lck":25,"cha":55}},{"slug":"tialla","stats":{"hp":30,"str":25,"mag":45,"spd":35,"dex":40,"def":20,"res":40,"lck":50,"cha":45}},{"slug":"peter","stats":{"hp":40,"str":35,"mag":20,"spd":45,"dex":60,"def":30,"res":25,"lck":35,"cha":30}},{"slug":"ultand","stats":{"hp":45,"str":40,"mag":40,"spd":35,"dex":40,"def":35,"res":45,"lck":55,"cha":50}},{"slug":"fabio","stats":{"hp":40,"str":25,"mag":50,"spd":35,"dex":40,"def":30,"res":45,"lck":35,"cha":30}},{"slug":"esmeralda","stats":{"hp":55,"str":55,"mag":20,"spd":35,"dex":35,"def":45,"res":25,"lck":35,"cha":30}},{"slug":"mikaela","stats":{"hp":50,"str":45,"mag":30,"spd":40,"dex":35,"def":40,"res":25,"lck":30,"cha":40}},{"slug":"bonaventure","stats":{"hp":35,"str":35,"mag":45,"spd":40,"dex":50,"def":30,"res":40,"lck":35,"cha":40}},{"slug":"tobias","stats":{"hp":55,"str":60,"mag":15,"spd":25,"dex":30,"def":45,"res":20,"lck":40,"cha":35}},{"slug":"lilian","stats":{"hp":35,"str":35,"mag":30,"spd":40,"dex":55,"def":30,"res":35,"lck":50,"cha":25}},{"slug":"lysander","stats":{"hp":45,"str":40,"mag":25,"spd":50,"dex":35,"def":40,"res":25,"lck":30,"cha":30}},{"slug":"buccar","stats":{"hp":50,"str":50,"mag":20,"spd":25,"dex":40,"def":45,"res":20,"lck":30,"cha":35}},{"slug":"sirocco","stats":{"hp":40,"str":40,"mag":40,"spd":45,"dex":50,"def":35,"res":35,"lck":50,"cha":45}},{"slug":"olympia","stats":{"hp":35,"str":35,"mag":50,"spd":35,"dex":35,"def":30,"res":40,"lck":40,"cha":40}},{"slug":"mu","stats":{"hp":50,"str":50,"mag":25,"spd":50,"dex":50,"def":40,"res":30,"lck":30,"cha":40}},{"slug":"gaitz","stats":{"hp":50,"str":50,"mag":20,"spd":40,"dex":45,"def":45,"res":25,"lck":40,"cha":45}},{"slug":"dante","stats":{"hp":30,"str":30,"mag":45,"spd":40,"dex":40,"def":20,"res":40,"lck":45,"cha":30}},{"slug":"ursula","stats":{"hp":40,"str":35,"mag":35,"spd":50,"dex":50,"def":35,"res":30,"lck":40,"cha":45}},{"slug":"simon","stats":{"hp":50,"str":50,"mag":20,"spd":35,"dex":40,"def":40,"res":25,"lck":50,"cha":35}},{"slug":"diego","stats":{"hp":45,"str":40,"mag":20,"spd":45,"dex":60,"def":35,"res":20,"lck":35,"cha":30}},{"slug":"ninae","stats":{"hp":45,"str":45,"mag":35,"spd":35,"dex":45,"def":35,"res":45,"lck":50,"cha":40}},{"slug":"sha-lan","stats":{"hp":35,"str":30,"mag":45,"spd":35,"dex":50,"def":30,"res":45,"lck":35,"cha":40}},{"slug":"nezha","stats":{"hp":45,"str":45,"mag":25,"spd":45,"dex":50,"def":35,"res":25,"lck":30,"cha":25}},{"slug":"guzran","stats":{"hp":45,"str":45,"mag":20,"spd":50,"dex":45,"def":35,"res":20,"lck":45,"cha":30}},{"slug":"io","stats":{"hp":45,"str":40,"mag":25,"spd":35,"dex":45,"def":40,"res":25,"lck":35,"cha":35}},{"slug":"catania","stats":{"hp":35,"str":35,"mag":35,"spd":55,"dex":50,"def":30,"res":35,"lck":40,"cha":45}},{"slug":"nydine","stats":{"hp":45,"str":40,"mag":30,"spd":45,"dex":40,"def":30,"res":25,"lck":35,"cha":35}},{"slug":"benditz","stats":{"hp":50,"str":35,"mag":20,"spd":35,"dex":50,"def":35,"res":25,"lck":30,"cha":35}},{"slug":"alexandra","stats":{"hp":30,"str":35,"mag":35,"spd":55,"dex":45,"def":30,"res":40,"lck":50,"cha":50}},{"slug":"yang-jie","stats":{"hp":50,"str":35,"mag":40,"spd":35,"dex":35,"def":30,"res":40,"lck":40,"cha":25}},{"slug":"noctula","stats":{"hp":50,"str":45,"mag":20,"spd":45,"dex":40,"def":40,"res":20,"lck":35,"cha":30}},{"slug":"sofia","stats":{"hp":35,"str":30,"mag":45,"spd":30,"dex":40,"def":25,"res":40,"lck":30,"cha":40}},{"slug":"peppe","stats":{"hp":30,"str":30,"mag":25,"spd":60,"dex":45,"def":30,"res":30,"lck":45,"cha":30}},{"slug":"seteth","stats":{"hp":45,"str":45,"mag":30,"spd":40,"dex":45,"def":40,"res":35,"lck":30,"cha":50}},{"slug":"loretta","stats":{"hp":35,"str":35,"mag":35,"spd":55,"dex":40,"def":30,"res":40,"lck":30,"cha":30}},{"slug":"jester","stats":{"hp":40,"str":35,"mag":15,"spd":60,"dex":45,"def":35,"res":25,"lck":40,"cha":40}},{"slug":"goliath","stats":{"hp":55,"str":60,"mag":5,"spd":15,"dex":30,"def":50,"res":20,"lck":35,"cha":20}},{"slug":"ludia","stats":{"hp":40,"str":35,"mag":20,"spd":55,"dex":45,"def":30,"res":20,"lck":30,"cha":30}},{"slug":"dadao","stats":{"hp":50,"str":55,"mag":20,"spd":30,"dex":35,"def":45,"res":20,"lck":25,"cha":30}},{"slug":"fianna","stats":{"hp":30,"str":35,"mag":55,"spd":30,"dex":40,"def":20,"res":45,"lck":25,"cha":40}},{"slug":"halvin","stats":{"hp":35,"str":35,"mag":30,"spd":45,"dex":60,"def":30,"res":25,"lck":40,"cha":35}},{"slug":"zarcone","stats":{"hp":40,"str":30,"mag":20,"spd":35,"dex":60,"def":30,"res":25,"lck":30,"cha":15}},{"slug":"majide","stats":{"hp":65,"str":50,"mag":15,"spd":20,"dex":30,"def":40,"res":10,"lck":25,"cha":5}},{"slug":"kiroc","stats":{"hp":55,"str":40,"mag":15,"spd":55,"dex":50,"def":30,"res":15,"lck":30,"cha":25}},{"slug":"jasmine","stats":{"hp":50,"str":40,"mag":20,"spd":30,"dex":45,"def":45,"res":25,"lck":40,"cha":45}},{"slug":"nuzzuo","stats":{"hp":50,"str":50,"mag":15,"spd":55,"dex":45,"def":20,"res":15,"lck":25,"cha":35}},{"slug":"inyoni","stats":{"hp":40,"str":50,"mag":20,"spd":35,"dex":40,"def":40,"res":30,"lck":40,"cha":30}},{"slug":"creek","stats":{"hp":45,"str":50,"mag":15,"spd":60,"dex":50,"def":35,"res":20,"lck":30,"cha":35}},{"slug":"nathan","stats":{"hp":55,"str":60,"mag":15,"spd":25,"dex":60,"def":45,"res":15,"lck":25,"cha":30}},{"slug":"bertrand","stats":{"hp":50,"str":55,"mag":15,"spd":45,"dex":50,"def":45,"res":20,"lck":30,"cha":50}},{"slug":"talimun","stats":{"hp":45,"str":40,"mag":45,"spd":40,"dex":45,"def":35,"res":40,"lck":60,"cha":50}},{"slug":"anatolia","stats":{"hp":40,"str":35,"mag":50,"spd":50,"dex":45,"def":35,"res":40,"lck":40,"cha":50}},{"slug":"orchel","stats":{"hp":30,"str":60,"mag":45,"spd":10,"dex":20,"def":60,"res":60,"lck":20,"cha":60}},{"slug":"centurio","stats":{"hp":45,"str":45,"mag":25,"spd":40,"dex":50,"def":50,"res":30,"lck":30,"cha":30}},{"slug":"aswan","stats":{"hp":40,"str":35,"mag":10,"spd":40,"dex":50,"def":30,"res":15,"lck":30,"cha":20}},{"slug":"tahonia","stats":{"hp":65,"str":50,"mag":5,"spd":20,"dex":40,"def":45,"res":35,"lck":20,"cha":40}},{"slug":"klapka","stats":{"hp":40,"str":40,"mag":10,"spd":25,"dex":45,"def":50,"res":15,"lck":25,"cha":35}}]$g$::jsonb) loop
    select k.id, v.content into c
    from public.cards k
    join public.card_pointers p on p.card_id = k.id and p.channel = 'stable'
    join public.card_revisions v on v.id = p.revision_id
    where k.game_id = 'fortunes-weave' and k.block_key = 'units' and k.slug = r->>'slug';
    continue when c.id is null or coalesce(c.content->'stats', '{}'::jsonb) @> (r->'stats');
    insert into public.card_revisions (card_id, content, summary)
    values (c.id, c.content || jsonb_build_object('stats', coalesce(c.content->'stats', '{}'::jsonb) || (r->'stats')), 'Stat growths added')
    returning id into rid;
    update public.card_pointers set revision_id = rid, updated_at = now() where card_id = c.id and channel = 'stable';
  end loop;
end $$;

-- Units with growths now (should be 63).
select count(*) as units_with_growths
from public.cards k
join public.card_pointers p on p.card_id = k.id and p.channel = 'stable'
join public.card_revisions v on v.id = p.revision_id
where k.game_id = 'fortunes-weave' and k.block_key = 'units' and v.content ? 'stats';
